CSS = '''
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f4f3ee;color:#193039;font:18px/1.65 Arial,Helvetica,sans-serif}main{display:block;max-width:920px;margin:auto;padding:38px 30px 70px}h1,h2,h3{line-height:1.2;color:#173a43}h1{font-size:43px;letter-spacing:-1px;margin:10px 0 20px}h2{font-size:27px;margin:0 0 22px}h3{font-size:21px}p{margin:14px 0}a{color:#006876;text-decoration-thickness:1px;text-underline-offset:3px}.eyebrow{font-size:12px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#536962}.lead{font-size:20px}.muted{color:#50636a}.small{font-size:14px}.scope{padding:18px 22px;background:#e6eee6;border-left:4px solid #597661;margin:24px 0}nav{padding:15px 0;border-top:1px solid #ccd8d4;border-bottom:1px solid #ccd8d4;line-height:2.1}nav a{white-space:nowrap;display:inline-block;margin-right:20px}article{background:white;border:1px solid #dce2dd;border-radius:8px;margin:28px 0;padding:28px}article p{max-width:75ch}.citations{font-size:12px;line-height:1.8;color:#50636a;margin-top:7px}.cite{display:inline-block;margin-right:12px}.evidence-link{margin-left:4px}figure{margin:24px 0 10px;padding:16px 0 0;border-top:1px solid #e0e5df;text-align:center}figure img{display:block;height:auto;max-width:100%;margin:auto}figcaption{font-size:13px;text-align:left;line-height:1.6;margin-top:10px}.note{background:#f1f4ef;padding:12px 16px;font-size:15px}.question-head{font-size:13px;color:#49625e;font-weight:bold;text-transform:uppercase;letter-spacing:.7px}.marks{float:right;color:#42605a}.answer-space{height:90px;border-bottom:1px dotted #ced8d2;margin:12px 0}.options{list-style-type:upper-alpha;padding-left:27px}.options li{margin:12px 0;padding-left:4px}.points{padding-left:23px}.points li{padding:5px 0}.point-mark{font-size:13px;color:#48675e}.correct{border-left:4px solid #5d816f;padding-left:15px}footer{border-top:1px solid #ccd8d4;margin-top:36px;padding-top:16px;font-size:13px;line-height:1.8}.source-file{overflow-wrap:break-word;word-wrap:break-word}li{margin:6px 0}.contents{columns:2;column-gap:30px;padding-left:0;list-style:none}.contents li{break-inside:avoid}.print-only{display:none}
@media(max-width:600px){body{font-size:17px}main{padding:23px 16px 40px}h1{font-size:33px}h2{font-size:24px}article{padding:20px 17px;margin:22px 0}.contents{columns:1}.scope{padding:14px 17px}nav a{margin-right:14px}figure{padding:10px 0}.marks{float:none;display:block}}
@media print{.sba-heading{page-break-before:always}body{background:white;font-size:11pt;line-height:1.5}main{max-width:none;padding:0}h1{font-size:27pt}h2{font-size:18pt}h3{font-size:13pt}nav,.no-print{display:none}.print-only{display:block}article{border:0;border-radius:0;padding:0;margin:22pt 0;page-break-inside:auto}h2,h3,.question-head{page-break-after:avoid}p,li{orphans:3;widows:3}.scope{padding:10pt 13pt}figure{page-break-inside:avoid}figure img{max-height:140mm;width:auto!important;max-width:100%}figcaption,.citations{font-size:8pt}.question,.answer,.section-start{page-break-inside:avoid}.answer-space{height:70pt}.contents{columns:1}.lead{font-size:12pt}a{color:#193039}.marks{float:right}footer{font-size:9pt;page-break-inside:avoid}}
'''
EXTRA_CSS='''
.marks{float:none;display:inline-block;margin-left:1em}h2,h3{page-break-inside:avoid;page-break-after:avoid}.question-head{page-break-after:avoid}
table{width:100%;border-collapse:collapse;font-size:16px;table-layout:fixed}th,td{padding:12px;vertical-align:top;text-align:left;border:1px solid #cbd7d0;word-break:normal;overflow-wrap:normal;hyphens:none}th{background:#e6eee6}caption{text-align:left;margin:12px 0}figure img{max-height:none}.scope strong{display:block}.block{margin:20px 0}
@media(max-width:600px){table,caption,tbody,tr,th,td{display:block;width:100%}thead{display:none}tr{margin:16px 0;border:1px solid #cbd7d0}td{border:0;padding:10px 12px}td:before{content:attr(data-label) ': ';display:block;font-weight:bold}figure img{max-height:none}}
@media print{table{font-size:9pt}tr{page-break-inside:avoid}figure img{max-height:200mm}.block{margin:12pt 0}.marks{float:none}}
'''
